function textoBot(textos, chave, vars = {}) {
  const t = textos?.[chave] ?? TEXTOS_PADRAO[chave] ?? chave;
  return render(t, vars);
}

// {chave} -> valor; chave sem valor fica vazia.
function render(t, vars = {}) {
  return String(t).replace(/\{(\w+)\}/g, (_, k) => (vars[k] ?? '') + '');
}

const TZ = 'America/Bahia';

function formatarData(iso) {
  if (!iso) return '';
  const d = new Date(iso);
  const dia = new Intl.DateTimeFormat('pt-BR', { timeZone: TZ, weekday: 'short', day: '2-digit', month: '2-digit' }).format(d);
  const hora = new Intl.DateTimeFormat('pt-BR', { timeZone: TZ, hour: '2-digit', minute: '2-digit' }).format(d);
  return `${dia.replace('.', '')} às ${hora}`;
}

function formatarPreco(v) {
  if (v === null || v === undefined || v === '') return '';
  return new Intl.NumberFormat('pt-BR', { style: 'currency', currency: 'BRL' }).format(Number(v)).replace(/\s/g, ' ');
}

function varsEvento(e) {
  if (!e) return {};
  return { nome: e.nome, evento: e.nome, data: formatarData(e.data_evento), local: e.local ?? '', link: e.link_compra ?? '', preco: formatarPreco(e.preco) };
}

function listaEventos(eventos) {
  return eventos.map((e, i) => `${i + 1} - ${e.nome} (${formatarData(e.data_evento)})`).join('\n');
}

// ── src/sql.js ──
// Monta o SQL que grava o resultado do core num único statement (CTEs).
// Literais escapados aqui (standard_conforming_strings=on, padrão do Postgres).



function lit(v) {
  if (v === null || v === undefined) return 'null';
  if (typeof v === 'number') return Number.isFinite(v) ? String(v) : 'null';
  if (typeof v === 'boolean') return v ? 'true' : 'false';
  if (typeof v === 'object') return `${lit(JSON.stringify(v))}::jsonb`;
  const s = String(v).replace(/\0/g, '').replace(/'/g, "''");
  // O node Postgres do n8n formata a query com pg-promise: "$1" num texto de cliente viraria
  // placeholder. Texto com $ vai como U&'' com o $ em \0024.
  if (!s.includes('$')) return `'${s}'`;
  return `U&'${s.replace(/\\/g, '\\\\').replace(/\$/g, '\\0024')}'`;
}

const COLUNAS_PEDIDO = ['comprovante_url', 'nome', 'cpf', 'email', 'status'];

// ctx = entrada do core; r = resultado de processar(). Devolve 1 linha: {pedido_id}.
function sqlGravar(ctx, r) {
  const ctes = [];
  const { novoPedido, atualizarPedido, novaOferta } = r.efeitos ?? {};
  const canal = lit(ctx.canal);
  const contato = lit(ctx.contato_id);

  if (novoPedido) {
    const p = novoPedido;
    ctes.push(`np as (insert into app.pedidos (canal, contato_id, evento_id, quantidade, valor_total, forma, status)
  values (${canal}, ${contato}, ${lit(p.evento_id)}, ${lit(p.quantidade)}, ${lit(p.valor_total)}, ${lit(p.forma)}, ${lit(p.status)}) returning id)`);
  }
  if (atualizarPedido?.id) {
    const sets = COLUNAS_PEDIDO.filter((k) => k in atualizarPedido).map((k) => `${k}=${lit(atualizarPedido[k])}`);
    ctes.push(`up as (update app.pedidos set ${sets.join(', ')}, atualizado_em=now()
  where id=${Number(atualizarPedido.id)} and canal=${canal} and contato_id=${contato} and status not in ('aprovado','recusado','cancelado'))`);
  }
  if (novaOferta) {
    const o = novaOferta;
    ctes.push(`nov as (insert into app.ofertas_venda (canal, contato_id, evento_texto, quantidade, setor, valor_pedido)
  values (${canal}, ${contato}, ${lit(o.evento_texto)}, ${lit(o.quantidade)}, ${lit(o.setor)}, ${lit(o.valor_pedido)}))`);
  }
  const hist = [];
  const entrada = [ctx.midia ? `[${ctx.midia.tipo}]` : '', ctx.texto ?? ''].filter(Boolean).join(' ');
  if (entrada) hist.push(['in', entrada]);
  for (const m of r.mensagens ?? []) hist.push(['out', m.texto ?? m.url ?? '']);
  if (hist.length) {
    ctes.push(`h as (insert into app.historico (canal, contato_id, direcao, texto) values
  ${hist.map(([d, t]) => `(${canal}, ${contato}, ${lit(d)}, ${lit(mascararCpfsNoTexto(t))})`).join(',\n  ')})`);
  }
  const ctxJson = lit(r.contexto ?? {});
  const ctxFinal = novoPedido ? `${ctxJson} || jsonb_build_object('pedido_id', (select id from np))` : ctxJson;
  ctes.push(`cv as (insert into app.conversas (canal, contato_id, nome, estado, contexto, pausado_ate, atualizado_em)
  values (${canal}, ${contato}, ${lit(ctx.nome || null)}, ${lit(r.estado)}, ${ctxFinal}, ${lit(r.pausado_ate)}, now())
  on conflict (canal, contato_id) do update set nome=coalesce(excluded.nome, app.conversas.nome), estado=excluded.estado,
  contexto=excluded.contexto, pausado_ate=excluded.pausado_ate, atualizado_em=now())`);
  return `with ${ctes.join(',\n')}\nselect ${novoPedido ? '(select id from np)' : 'null::int'} as pedido_id`;
}

// Tudo que o core precisa numa ida ao banco: conversa, eventos ativos, textos e config.
function sqlCarregar(canal, contatoId) {
  return `select
  (select to_jsonb(c) from app.conversas c where c.canal=${lit(canal)} and c.contato_id=${lit(contatoId)}) as conversa,
  (select coalesce(jsonb_agg(to_jsonb(e) order by e.data_evento), '[]') from app.eventos e where e.ativo) as eventos,
  (select coalesce(jsonb_object_agg(chave, texto), '{}') from app.mensagens) as textos,
  (select coalesce(jsonb_object_agg(chave, valor), '{}') from app.config) as config,
  now() as agora`;
}

// ── src/canais.js ──
// Adaptadores: Evolution (WhatsApp) e ManyChat (Instagram) <-> formato do core.
// Mensagem do core: {tipo:'texto', texto} | {tipo:'imagem'|'documento', url?|base64?, texto?, mimetype?, fileName?}

// Celular BR: o WhatsApp às vezes entrega 5571 + 8 dígitos (sem o 9 extra) e a gente guarda com 9.
// Devolve as formas equivalentes do mesmo número, para comparar e para buscar no banco.
function variantesNumero(n) {
  const d = String(n ?? '').replace(/\D/g, '');
  const sem9 = d.match(/^(55\d{2})(\d{8})$/);
  const com9 = d.match(/^(55\d{2})9(\d{8})$/);
  return [d, sem9 && `${sem9[1]}9${sem9[2]}`, com9 && `${com9[1]}${com9[2]}`].filter(Boolean);
}

// Webhook messages.upsert da Evolution v2 -> {id, contato_id, nome, texto, midia, fromMe} ou null (ignorar).
// Mensagens enviadas pela API não voltam aqui (emitOwnEvents=false): fromMe = alguém digitou no celular.
function normalizarEvolution(body) {
  if (!body || body.event !== 'messages.upsert') return null;
  const d = Array.isArray(body.data) ? body.data[0] : body.data;
  const key = d?.key ?? {};
  const jid = key.remoteJidAlt && String(key.remoteJid).endsWith('@lid') ? key.remoteJidAlt : key.remoteJid;
  if (!jid || !key.id) return null;
  if (/@(g\.us|broadcast|newsletter)$/.test(jid)) return null; // grupos, status, canais
  const m = d.message ?? {};
  const texto = m.conversation ?? m.extendedTextMessage?.text ?? m.imageMessage?.caption ?? m.documentMessage?.caption
    ?? m.documentWithCaptionMessage?.message?.documentMessage?.caption ?? m.buttonsResponseMessage?.selectedDisplayText
    ?? m.listResponseMessage?.title ?? '';
  let midia = null;
  const doc = m.documentMessage ?? m.documentWithCaptionMessage?.message?.documentMessage;
  if (m.imageMessage) midia = { tipo: 'imagem', mimetype: m.imageMessage.mimetype ?? 'image/jpeg' };
  else if (doc) midia = { tipo: 'documento', mimetype: doc.mimetype ?? '', fileName: doc.fileName ?? 'arquivo' };
  else if (m.audioMessage || m.videoMessage || m.stickerMessage) midia = { tipo: m.audioMessage ? 'audio' : m.videoMessage ? 'video' : 'sticker' };
  if (midia) {
    midia.ref = `wa:${key.id}`;
    if (m.base64) midia.base64 = m.base64;
  }
  if (!texto && !midia) return null; // reação, protocolo, enquete...
  return {
    id: key.id,
    contato_id: String(jid).split('@')[0],
    nome: key.fromMe ? null : d.pushName || null,
    texto: String(texto).trim(),
    midia,
    fromMe: !!key.fromMe,
  };
}

// Mensagens do core -> chamadas da Evolution. `numero` = dígitos ou JID de grupo.
// O `delay` da Evolution mostra "digitando..." antes de enviar (anti-ban: 1–4 s pelo tamanho).
function chamadasEvolution(numero, mensagens) {
  return (mensagens ?? []).map((m) => {
    const delay = atrasoDigitando(m.texto);
    if (m.tipo === 'texto') return { endpoint: 'sendText', body: { number: numero, text: m.texto, delay } };
    const mediatype = m.tipo === 'imagem' ? 'image' : 'document';
    const body = { number: numero, mediatype, media: m.base64 ?? m.url, caption: m.texto ?? '', delay };
    if (m.mimetype) body.mimetype = m.mimetype;
    if (mediatype === 'document') body.fileName = m.fileName ?? 'comprovante.pdf';
    return { endpoint: 'sendMedia', body };
  });
}

function atrasoDigitando(texto) {
  return Math.min(4000, Math.max(1000, 1000 + String(texto ?? '').length * 25));
}

// Corpo do External Request do ManyChat (ver manychat/SETUP.md). Aceita o corpo montado
// ({contato_id, nome, texto, comprovante_url}) e o "Full Contact Data" ({id, name, last_input_text, custom_fields}).
function normalizarManychat(body) {
  const b = body ?? {};
  const contato = String(b.contato_id ?? b.id ?? '').trim();
  if (!contato) return null;
  let texto = String(b.texto ?? b.last_input_text ?? '').trim();
  const url = String(b.comprovante_url ?? b.custom_fields?.comprovante_url ?? '').trim() || (/^https?:\/\/\S+$/.test(texto) && /cdn|fbsbx|lookaside|instagram/.test(texto) ? texto : '');
  if (url && url === texto) texto = '';
  return {
    contato_id: contato,
    nome: String(b.nome ?? b.name ?? '').trim() || null,
    texto,
    midia: url ? { tipo: /\.pdf(\?|$)/i.test(url) ? 'documento' : 'imagem', url, mimetype: /\.pdf(\?|$)/i.test(url) ? 'application/pdf' : 'image/jpeg' } : null,
  };
}

// Resposta Dynamic Block v2 (Instagram): até 10 mensagens; só texto e imagem.
// A action grava o estado no campo `estado` do ManyChat (o fluxo usa para pedir o comprovante).
function respostaManychat(mensagens, estado) {
  const msgs = (mensagens ?? []).flatMap((m) => {
    if (m.tipo === 'imagem' && m.url) return [{ type: 'image', url: m.url }, ...(m.texto ? [{ type: 'text', text: m.texto }] : [])];
    return m.texto ? [{ type: 'text', text: m.texto }] : [];
  }).slice(0, 10);
  const content = { type: 'instagram', messages: msgs, actions: [], quick_replies: [] };
  if (estado) {
    content.actions.push({ action: 'set_field_value', field_name: 'estado', value: estado });
    content.actions.push({ action: 'unset_field_value', field_name: 'comprovante_url' }); // já foi lido; não reenviar
  }
  return { version: 'v2', content };
}

// Corpo do sendContent da API do ManyChat (aviso de /aprovar e /recusar no Instagram).
function sendContentManychat(subscriberId, mensagens) {
  const { content } = respostaManychat(mensagens, null);
  delete content.actions;
  delete content.quick_replies;
  return { subscriber_id: Number(subscriberId), data: { version: 'v2', content } };
}

// ── src/comandos.js ──
// Comandos do admin (/aprovar, /recusar, /pedidos, /pausar, /retomar, /eventos, /ajuda):
// parse -> SQL -> texto de resposta. O painel usa o mesmo caminho.






const AJUDA = [
  'Comandos:',
  '/pedidos — pedidos em aberto',
  '/aprovar <id> — aprova e avisa o cliente',
  '/recusar <id> [motivo] — recusa e avisa o cliente',
  '/pausar <tel> — pausa o bot nesse chat',
  '/retomar <tel> — devolve o chat ao bot',
  '/eventos — eventos ativos',
  '/ajuda — esta lista',
].join('\n');

// 71 99999-9999 -> 5571999999999; ids longos (Instagram) passam direto.
function normalizarContato(s) {
  const d = soDigitos(s);
  if (d.length === 10 || d.length === 11) return '55' + d;
  return d.length >= 12 ? d : null;
}

function parseComando(texto) {
  const m = String(texto ?? '').trim().match(/^\/(\w+)\s*([\s\S]*)$/);
  if (!m) return null;
  const cmd = m[1].toLowerCase();
  const resto = m[2].trim();
  switch (cmd) {
    case 'aprovar':
    case 'recusar': {
      const r = resto.match(/^#?(\d+)\s*([\s\S]*)$/);
      if (!r) return { erro: `Uso: /${cmd} <id>${cmd === 'recusar' ? ' [motivo]' : ''}` };
      return cmd === 'aprovar' ? { cmd, id: Number(r[1]) } : { cmd, id: Number(r[1]), motivo: r[2].trim() || null };
    }
    case 'pausar':
    case 'retomar': {
      const contato = normalizarContato(resto);
      return contato ? { cmd, contato } : { erro: `Uso: /${cmd} <telefone com DDD>` };
    }
    case 'pedidos':
    case 'eventos':
    case 'ajuda':
      return { cmd };
    default:
      return { erro: 'Comando desconhecido. Manda /ajuda.' };
  }
}

const TEXTOS = '(select coalesce(jsonb_object_agg(chave, texto), \'{}\') from app.mensagens) as textos';
const ABERTOS = "('aguardando_comprovante','coletando_dados','aguardando_validacao')";

// SQL que executa o comando (um statement; devolve linhas para formatarResposta).
function sqlComando(c, { pausaHoras = 12 } = {}) {
  switch (c.cmd) {
    case 'aprovar':
    case 'recusar': {
      const status = c.cmd === 'aprovar' ? 'aprovado' : 'recusado';
      return `with p as (update app.pedidos set status=${lit(status)}, motivo_recusa=${lit(c.motivo ?? null)}, atualizado_em=now()
  where id=${Number(c.id)} and status in ${ABERTOS} returning *),
cv as (update app.conversas cv set estado='inicio', contexto='{}'::jsonb, atualizado_em=now()
  from p where cv.canal=p.canal and cv.contato_id=p.contato_id and cv.contexto->>'pedido_id'=p.id::text)
select p.id, p.canal, p.contato_id, p.quantidade, p.valor_total, p.status, p.motivo_recusa, e.nome as evento, ${TEXTOS}
from p left join app.eventos e on e.id=p.evento_id`;
    }
    case 'pedidos':
      return `select p.id, p.canal, p.contato_id, p.quantidade, p.valor_total, p.status, p.nome, p.cpf, e.nome as evento
from app.pedidos p left join app.eventos e on e.id=p.evento_id where p.status in ${ABERTOS} order by p.id limit 30`;
    case 'pausar':
      return `with u as (update app.conversas set estado='humano', pausado_ate=now()+make_interval(hours=>${Number(pausaHoras)}), atualizado_em=now()
  where contato_id = any(array[${variantesNumero(c.contato).map(lit).join(',')}]) returning canal),
i as (insert into app.conversas (canal, contato_id, estado, pausado_ate)
  select 'whatsapp', ${lit(c.contato)}, 'humano', now()+make_interval(hours=>${Number(pausaHoras)}) where not exists (select 1 from u) returning canal)
select canal from u union all select canal from i`;
    case 'retomar':
      return `update app.conversas set estado='inicio', contexto='{}'::jsonb, pausado_ate=null, atualizado_em=now()
where contato_id = any(array[${variantesNumero(c.contato).map(lit).join(',')}]) returning canal`;
    case 'eventos':
      return 'select id, nome, data_evento, local, preco from app.eventos where ativo order by data_evento';
    default:
      return 'select 1 where false';
  }
}

// rows = resultado do SQL. Devolve {admin: texto, cliente: {canal, contato_id, mensagens} | null}.
function formatarResposta(c, rows = []) {
  rows = rows.filter((r) => r && Object.keys(r).length);
  if (c.erro) return { admin: c.erro, cliente: null };
  switch (c.cmd) {
    case 'ajuda':
      return { admin: AJUDA, cliente: null };
    case 'aprovar':
    case 'recusar': {
      const p = rows[0];
      if (!p) return { admin: `Pedido #${c.id} não encontrado ou já finalizado.`, cliente: null };
      const chave = c.cmd === 'aprovar' ? 'pedido_aprovado' : 'pedido_recusado';
      const txt = textoBot(p.textos, chave, { pedido_id: p.id, evento: p.evento ?? '', motivo: p.motivo_recusa ? ` Motivo: ${p.motivo_recusa}.` : '' });
      return {
